SELECT CASE WHEN s.rating >= 4.0 THEN 'high' WHEN s.rating >= 1.7 THEN 'mid' ELSE 'low' END rating_bucket, s.country, MIN(ss.units) min_units, MAX(ss.revenue) - MIN(ss.revenue) revenue_range FROM store_sales ss JOIN products p ON p.id = ss.product_id LEFT JOIN suppliers s ON p.supplier_id = s.id WHERE ss.sale_date >= '2024-12-01' GROUP BY CASE WHEN s.rating >= 4.0 THEN 'high' WHEN s.rating >= 1.7 THEN 'mid' ELSE 'low' END, s.country ORDER BY country, rating_bucket LIMIT 10
